insert into public.daisy_call_scripts (created_by,title,category,direction,content) select user_id,'Engaged / Preparation — Progress Check','Workflow','outbound','{"title":"Engaged / Preparation — Progress Check","objective":"Review the buyer’s current milestone, address the obstacle, and agree on the next checkpoint.","opening":"Hi {first_name}, this is Daisy with the DPA Help Center. Is this {first_name} speaking?","script_text":"Hi {first_name}, this is Daisy with the DPA Help Center. Is this {first_name} speaking?\n\nI’m following up on your homebuyer preparation in Prep Hub. How have things been going with the step you’re working on?\n\nWhat have you been able to complete so far?\n\nIs anything making the next step difficult?\n\nLet’s agree on the next step based on where you are now. When do you expect to have that completed?\n\nWhen would be a good time for me to follow up with you to see how that step went?\n\nThank you, {first_name}. I’ll keep your update with your preparation record. We’ll take this one step at a time.","boundaries":["Ask one question at a time, listen, address the answer, and continue from the next unfinished checkpoint.","Use saved preparation evidence and prior conversation to personalize the next step. Do not restart the login orientation or repeat completed questions.","If the client needs a callback, confirm the date, time and timezone and save it before claiming it is scheduled.","Never invent completed tasks, eligibility, approval, a referral, or a scheduled callback."],"key_points":["Follow the saved stage objective and current client evidence."],"questions":[],"voicemail":"","recording_requested":true}'::jsonb from public.manager_members where role='owner' and active=true and not exists(select 1 from public.daisy_call_scripts where title='Engaged / Preparation — Progress Check' and deleted_at is null and archived_at is null) limit 1 returning id,script_number,title;
insert into public.daisy_call_scripts (created_by,title,category,direction,content) select user_id,'DPA Ready — Handoff Follow-up','Workflow','outbound','{"title":"DPA Ready — Handoff Follow-up","objective":"Confirm the buyer’s homebuying plans and coordinate the recorded preparation handoff.","opening":"Hi {first_name}, this is Daisy with the DPA Help Center. Is this {first_name} speaking?","script_text":"Hi {first_name}, this is Daisy with the DPA Help Center. Is this {first_name} speaking?\n\nI’m following up on the next step after your homebuyer preparation. Are you still planning to move forward with buying a home?\n\nWhat area are you looking in, and what timeline do you have in mind?\n\nHas anyone from our team already contacted you about the next step?\n\nWhat questions would you like me to pass along to the team?\n\nWhen is a good time for the team to reach you, and what time zone are you in?\n\nThank you, {first_name}. I’ll record your update so the team can follow up on your next step.","boundaries":["Ask one question at a time and respond to the actual answer before continuing.","DPA Ready means a preparation handoff was recorded. It does not mean lender approval, program approval, an award or guaranteed funds.","Use the recorded handoff and current client history; do not restart preparation or claim a transfer was completed without confirmation.","Record the requested contact window as a preference. Only call it a confirmed appointment or callback after the scheduling tool succeeds."],"key_points":["Follow the saved stage objective and current client evidence."],"questions":[],"voicemail":"","recording_requested":true}'::jsonb from public.manager_members where role='owner' and active=true and not exists(select 1 from public.daisy_call_scripts where title='DPA Ready — Handoff Follow-up' and deleted_at is null and archived_at is null) limit 1 returning id,script_number,title;
